export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.useRightHandedSystem = true;
  scene.clearColor = BABYLON.Color4.FromHexString("#4b5d99ff");

  const link = document.createElement("link");
  link.href = "https://fonts.googleapis.com/css2?family=Anton&family=Bebas+Neue&family=Rajdhani:wght@600&family=Roboto&display=swap";
  link.rel = "stylesheet";
  document.head.appendChild(link);

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.07, 1.4, 0.06));
  camera.alpha = 1.065;
  camera.beta = 1.473;
  camera.radius = 4.5;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 0;
  camera.minZ = 0.01;
  camera.maxZ = 10000;

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.6;

  var dirLight = new BABYLON.DirectionalLight("dir light", new BABYLON.Vector3(0.17, -1, -1), scene);
  dirLight.position = new BABYLON.Vector3(5, 5, 5);
  dirLight.intensity = 1;

  dirLight.shadowMinZ = 0;
  dirLight.shadowMaxZ = 3000;

  var shadowGenerator = new BABYLON.ShadowGenerator(1024, dirLight);
  shadowGenerator.usePoissonSampling = true;

  let lightDirection = dirLight.direction;
  let cameraPosition = scene.activeCamera.globalPosition;

  let shadowGenerator_D = new BABYLON.ShadowGenerator(1024, dirLight);
  shadowGenerator_D.useExponentialShadowMap = true;
  shadowGenerator_D.filteringQuality = BABYLON.ShadowGenerator.QUALITY_HIGH;
  shadowGenerator_D.bias = 0.001;
  shadowGenerator_D._darkness = -10.0;

  const cloudTex = new BABYLON.Texture("/images/textures/cloud.png", scene);

  var groundMaterial = new BABYLON.GridMaterial("groundMaterial", scene);
  groundMaterial.majorUnitFrequency = 5;
  groundMaterial.minorUnitVisibility = 0.5;
  groundMaterial.gridRatio = 5;
  groundMaterial.lineColor = BABYLON.Color3.White();
  groundMaterial.opacity = 0.3;
  groundMaterial.useMaxLine = true;
  groundMaterial.opacityTexture = cloudTex;

  const shadowReceiver = BABYLON.MeshBuilder.CreateGround("groundShadow", { width: 10, height: 10 }, scene);
  shadowReceiver.material = new BABYLON.StandardMaterial("groundShadowMaterial", scene);
  shadowReceiver.material.alpha = 0.17;
  shadowReceiver.material.opacityTexture = cloudTex;

  shadowReceiver.receiveShadows = true;

  const gridOverlay = BABYLON.MeshBuilder.CreateGround("gridOverlay", { width: 10, height: 10 }, scene);
  gridOverlay.material = groundMaterial;
  gridOverlay.isPickable = false;
  gridOverlay.position.y += 0.001;

  let rootMesh;
  let isDragging = false;
  let lastX = 0;
  const MAX_ROT_DEG = 175;
  const MAX_ROT_Y = BABYLON.Angle.FromDegrees(MAX_ROT_DEG).radians();

  // const edgeDetectionPP = new BABYLON.EdgeDetectionPostProcess("Edge PP", scene, 1, camera);
  // edgeDetectionPP.samples = 4;
  // edgeDetectionPP.edgeIntensity = 1.0;
  // edgeDetectionPP.edgeWidth = .13;
  // edgeDetectionPP.edgeColor = new BABYLON.Color3(0, 0, 0);

  var hl1 = new BABYLON.HighlightLayer("hl1", scene, {
    isStroke: true,
    mainTextureRatio: 1,
    blurVerticalSize: 0.025,
    blurHorizontalSize: 0.025,
  });

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "thor__marvel_rivals.glb").then((result) => {
    rootMesh = result.meshes[0];
    rootMesh.normalizeToUnitCube = true;

    rootMesh.rotation.y = Math.PI / 4;

    rootMesh.getChildMeshes().forEach((m) => {
      shadowGenerator_D.addShadowCaster(m);

      hl1.addMesh(m, BABYLON.Color3.Black());
    });

    pointerHandler();

    function applyRimToonShader() {
      const baseVertexShader = `
        varying vec3 vNormal;
        varying vec3 vViewDir;
        varying vec4 vWorldPosition;
        varying vec4 vPositionFromLight;
        varying vec2 vUV;

        uniform mat4 world;
        uniform mat4 worldViewProjection;
        uniform mat4 lightMatrix;

        attribute vec3 position;
        attribute vec3 normal;
        attribute vec2 uv;

        #ifdef SKELETON
        attribute vec4 matricesIndices;
        attribute vec4 matricesWeights;
        uniform mat4 mBones[600];
        #endif

        void main() {
            vec4 finalPosition = vec4(position, 1.0);
            vec3 finalNormal = normal;

            #ifdef SKELETON
            finalPosition = vec4(0.0);
            finalNormal = vec3(0.0);
            for (int i = 0; i < 4; ++i) {
                int boneIndex = int(matricesIndices[i]);
                mat4 boneMatrix = mBones[boneIndex];
                finalPosition += boneMatrix * vec4(position, 1.0) * matricesWeights[i];
                finalNormal += (boneMatrix * vec4(normal, 0.0)).xyz * matricesWeights[i];
            }
            #endif

            vWorldPosition = world * finalPosition;
            gl_Position = worldViewProjection * finalPosition;
            vNormal = normalize(mat3(world) * finalNormal); // 정상 벡터 변환
            vViewDir = normalize(-vWorldPosition.xyz);

            vPositionFromLight = lightMatrix * vWorldPosition;
            vUV = uv;
        }
    `;

      const baseFragmentShader = `
        varying vec3 vNormal;
        varying vec3 vViewDir;
        varying vec4 vWorldPosition;
        varying vec4 vPositionFromLight;
        varying vec2 vUV;

        uniform vec3 uColor;
        uniform float uGlossiness;
        uniform vec3 lightDirection;
        uniform vec3 lightColor;
        uniform vec3 ambientColor;
        uniform vec3 cameraPosition;
        uniform sampler2D shadowMap;

        uniform sampler2D albedoTexture;
        uniform float hasAlbedoTexture;
        uniform float dirIntensity;

        float unpackDepth(const in vec4 rgbaDepth) {
            const vec4 bitShift = vec4(1.0 / (256.0 * 256.0 * 256.0), 1.0 / (256.0 * 256.0), 1.0 / 256.0, 1.0);
            float depth = dot(rgbaDepth, bitShift);
            return depth;
        }

        void main() {
            vec3 norm = normalize(vNormal);
            vec3 viewDir = normalize(cameraPosition - vWorldPosition.xyz);
            vec3 lightDir = normalize(-lightDirection);

            vec3 shadowCoord = vPositionFromLight.xyz / vPositionFromLight.w;
            shadowCoord = shadowCoord * 0.5 + 0.5;
            bool inShadow = texture2D(shadowMap, shadowCoord.xy).r < shadowCoord.z;
            float shadow = inShadow ? 0.0 : 1.0;

            float NdotL = max(dot(norm, lightDir), 0.0);
            NdotL *= shadow;
            float lightIntensity = smoothstep(0.0, 0.01, NdotL);
            vec3 directionalLight = lightColor * lightIntensity * dirIntensity;

            // specular reflection
            vec3 halfVector = normalize(lightDir + viewDir);
            float NdotH = max(dot(norm, halfVector), 0.0);
            float specularIntensity = pow(NdotH * lightIntensity, 1000.0 / uGlossiness);
            float specularIntensitySmooth = smoothstep(0.05, 0.1, specularIntensity);
            vec3 specular = specularIntensitySmooth * lightColor;

            // rim lighting
            float rimDot = 1.0 - dot(viewDir, norm);
            float rimThreshold = 0.2;
            float rimIntensity = rimDot * pow(NdotL, rimThreshold);
            rimIntensity = smoothstep(0.6 - 0.01, 0.6 + 0.01, rimIntensity);
            vec3 rim = rimIntensity * lightColor;

            vec4 albedoColor;
            if (hasAlbedoTexture > 0.5) {
                albedoColor = texture2D(albedoTexture, vUV);
            } else {
                albedoColor = vec4(uColor, 1.0);
            }

            vec3 finalColor = albedoColor.rgb * (ambientColor + directionalLight + specular + rim);
            gl_FragColor = vec4(finalColor, albedoColor.a);
        }
    `;

      function createShaderCode(baseCode, defines) {
        return defines.join("\n") + "\n" + baseCode;
      }

      rootMesh.getChildMeshes().forEach((m) => {
        var albedoT = m.material.albedoTexture;

        var defines = [];
        if (m.skeleton) {
          defines.push("#define SKELETON");
        }

        const vertexShaderCode = createShaderCode(baseVertexShader, defines);
        const fragmentShaderCode = createShaderCode(baseFragmentShader, defines);

        BABYLON.Effect.ShadersStore["rimLightToonVertexShader"] = vertexShaderCode;
        BABYLON.Effect.ShadersStore["rimLightToonFragmentShader"] = fragmentShaderCode;

        var clonedShaderMat = new BABYLON.ShaderMaterial(
          "toonShader",
          scene,
          {
            vertex: "rimLightToon",
            fragment: "rimLightToon",
          },
          {
            attributes: ["position", "normal", "uv", "matricesIndices", "matricesWeights"],
            uniforms: [
              "world",
              "worldView",
              "worldViewProjection",
              "view",
              "projection",
              "uColor",
              "uGlossiness",
              "lightDirection",
              "lightColor",
              "ambientColor",
              "cameraPosition",
              "hasAlbedoTexture",
              "dirIntensity",
              "mBones",
            ],
            samplers: ["albedoTexture", "shadowMap"],
          }
        );

        clonedShaderMat.setColor3("lightColor", new BABYLON.Color3(255 / 255, 178 / 255, 91 / 255));
        clonedShaderMat.setColor3("ambientColor", new BABYLON.Color3(1, 1, 1));
        clonedShaderMat.setColor3("uColor", new BABYLON.Color3(1, 1, 1));
        clonedShaderMat.setFloat("uGlossiness", 30);
        clonedShaderMat.setFloat("dirIntensity", 0.25);

        if (albedoT) {
          clonedShaderMat.setTexture("albedoTexture", albedoT);
          clonedShaderMat.setFloat("hasAlbedoTexture", 1.0);
        } else {
          clonedShaderMat.setFloat("hasAlbedoTexture", 0.0);
          if (m.material.albedoColor !== BABYLON.Color3.White()) {
            clonedShaderMat.setColor3("uColor", m.material.albedoColor);
          }
        }

        clonedShaderMat.setVector3("lightDirection", lightDirection.normalize());
        clonedShaderMat.setVector3("cameraPosition", cameraPosition);
        clonedShaderMat.setMatrix("lightMatrix", shadowGenerator_D.getTransformMatrix());
        clonedShaderMat.setTexture("shadowMap", shadowGenerator_D.getShadowMap());

        if (m.skeleton) {
          const boneMatrices = m.skeleton.getTransformMatrices(m);
          if (!(boneMatrices instanceof Float32Array)) {
            console.error("Bone matrices are not a Float32Array");
          }

          clonedShaderMat.onBindObservable.add(() => {
            clonedShaderMat.getEffect().setMatrices("mBones", boneMatrices);
          });
        }

        if (m.material.albedoTexture?.hasAlpha || m.material.useAlphaFromAlbedoTexture || m.material.alpha !== 1) {
          // Handle transparency if needed
        } else {
          m.material = clonedShaderMat;
        }
      });

      scene.enablePrePassRenderer();
    }

    applyRimToonShader();

    var pp = new BABYLON.DefaultRenderingPipeline("pp", true, scene);
    pp.fxaaEnabled = true;
    pp.imageProcessing.contrast = 1.5;
    pp.imageProcessing.exposure = 0.8;
    // pp.imageProcessing.vignetteEnabled = true;
    // pp.imageProcessing.vignetteWeight = 4;
    // pp.imageProcessing.vignetteColor = BABYLON.Color3.FromHexString("#716FC3");
    pp.samples = 4;
    // pp.samples = engine.getCaps().maxMSAASamples;
    engine.setHardwareScalingLevel(0.9);
  });

  const backgroundLayer = new BABYLON.Layer("bg", null, scene, true);
  backgroundLayer.texture = new BABYLON.Texture(
    "/images/textures/marvel_thor_bg.png",
    scene,
    false,
    true,
    BABYLON.Texture.TRILINEAR_SAMPLINGMODE,
    null,
    null,
    false
  );

  //const backgroundLayer1 = new BABYLON.Layer("bg1", null, scene, true);
  // backgroundLayer1.texture = new BABYLON.Texture(
  //   "/images/textures/marvel_bg1.png",
  //   scene,
  //   false,
  //   true,
  //   BABYLON.Texture.TRILINEAR_SAMPLINGMODE,
  //   null,
  //   null,
  //   false
  // );
  // const backgroundLayer2 = new BABYLON.Layer("bg2", null, scene, true);
  // backgroundLayer2.texture = new BABYLON.Texture(
  //   "/images/textures/marvel_bg2.png",
  //   scene,
  //   false,
  //   true,
  //   BABYLON.Texture.TRILINEAR_SAMPLINGMODE,
  //   null,
  //   null,
  //   false
  // );

  function pointerHandler() {
    if (rootMesh) {
      scene.onPointerObservable.add((pointerInfo) => {
        switch (pointerInfo.type) {
          case BABYLON.PointerEventTypes.POINTERDOWN:
            if (pointerInfo.event.button === 0) {
              isDragging = true;
              lastX = pointerInfo.event.clientX;
            }
            break;

          case BABYLON.PointerEventTypes.POINTERUP:
            if (pointerInfo.event.button === 0) {
              isDragging = false;
            }
            break;

          case BABYLON.PointerEventTypes.POINTERMOVE:
            if (isDragging) {
              const deltaX = pointerInfo.event.clientX - lastX;
              let nextRotY = rootMesh.rotation.y + deltaX * 0.005;
              nextRotY = Math.max(-MAX_ROT_Y, Math.min(MAX_ROT_Y, nextRotY));
              rootMesh.rotation.y = nextRotY;
              lastX = pointerInfo.event.clientX;
            }
            break;
          default:
            break;
        }
      });
    }
  }

  function setGUI() {
    const advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

    const panel = new BABYLON.GUI.StackPanel();
    panel.width = "50%";
    panel.height = "50%";
    panel.top = "100px";
    panel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
    panel.paddingLeft = "150px";
    advancedTexture.addControl(panel);

    const vanguardText = new BABYLON.GUI.TextBlock();
    vanguardText.text = "VANGUARD";
    vanguardText.color = "#101010";
    vanguardText.fontSize = "24px";
    vanguardText.height = "30px";
    vanguardText.top = "50%";
    vanguardText.fontFamily = "Bebas Neue";
    vanguardText.fontStyle = "italic bold";
    vanguardText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    panel.addControl(vanguardText);

    const thorText = new BABYLON.GUI.TextBlock();
    thorText.text = "THOR";
    thorText.color = "#101010";
    thorText.fontSize = "96px";
    thorText.height = "100px";
    thorText.paddingLeft = "-10px";
    thorText.fontFamily = "Anton";
    thorText.fontStyle = "italic bold";

    thorText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    panel.addControl(thorText);

    const odinsonText = new BABYLON.GUI.TextBlock();
    odinsonText.text = "THOR ODINSON";
    odinsonText.color = "#101010";
    odinsonText.fontSize = "20px";
    odinsonText.height = "30px";
    odinsonText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    odinsonText.paddingTop = "50px";
    odinsonText.fontFamily = "Rajdhani 600";
    odinsonText.fontStyle = "italic bold";
    panel.addControl(odinsonText);

    const descText = new BABYLON.GUI.TextBlock();
    descText.text =
      "The son of Odin taps into his divine power to call forth thunder and lightning, raining\n" +
      "down relentless fury upon his enemies. With his mighty hammer Mjolnir in hand,\n" +
      "Thor effortlessly asserts his dominance on the field of combat.";
    descText.color = "#101010";
    descText.fontSize = "16px";
    descText.fontFamily = "Roboto";
    descText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    descText.textWrapping = true;
    descText.paddingTop = "10px";
    descText.height = "120px";
    panel.addControl(descText);
  }
  // setGUI();
  return scene;
}
